const InvoiceOverviewDashboard = (props) => {
  const {
    title = 'Invoice Overview',
    generatedAt,
    clientsSummary = [],
    invoices = [],
    cashflowPoints = [],
    metrics = {},
    filterSummary = {},
    displayOptions = {},
    notes = []
  } = props;

  const currencySymbol = displayOptions.currencySymbol || metrics.currencySymbol || (displayOptions.currency || metrics.currency || '$');

  const formatCurrency = (value) => {
    const n = Number(value);
    if (isNaN(n)) {
      return value || `${currencySymbol}0.00`;
    }
    try {
      if (displayOptions.locale && (displayOptions.currency || metrics.currencyCode)) {
        return new Intl.NumberFormat(displayOptions.locale, {
          style: 'currency',
          currency: displayOptions.currency || metrics.currencyCode || 'USD'
        }).format(n);
      }
    } catch (e) {}
    return `${currencySymbol}${n.toFixed(2)}`;
  };

  const formatDate = (value) => {
    if (!value) {
      return '-';
    }
    const d = new Date(value);
    if (isNaN(d.getTime())) {
      return String(value);
    }
    return d.toLocaleDateString();
  };

  const computed = (() => {
    let totalAmount = 0;
    let paidAmount = 0;
    let overdueAmount = 0;
    let outstandingAmount = 0;
    const now = new Date();

    if (Array.isArray(invoices)) {
      invoices.forEach((inv) => {
        const amt = Number(inv.amount || inv.total || inv.value || 0);
        const status = (inv.status || '').toString().toLowerCase();
        totalAmount += isNaN(amt) ? 0 : amt;

        const isPaid = status.includes('paid') || status === 'closed' || status === 'completed';
        const isPartial = status.includes('partial');
        const dueDate = inv.dueDate ? new Date(inv.dueDate) : null;
        const paidVal = Number(inv.paid || inv.amountPaid || (isPaid ? amt : 0));
        const safePaid = isNaN(paidVal) ? 0 : paidVal;

        if (isPaid) {
          paidAmount += safePaid || amt;
        } else if (isPartial) {
          paidAmount += safePaid;
          outstandingAmount += Math.max(0, amt - safePaid);
          if (dueDate && !isNaN(dueDate.getTime()) && dueDate < now) {
            overdueAmount += Math.max(0, amt - safePaid);
          }
        } else {
          outstandingAmount += amt;
          if (dueDate && !isNaN(dueDate.getTime()) && dueDate < now) {
            overdueAmount += amt;
          }
        }
      });
    }

    const invoiceCount = Array.isArray(invoices) ? invoices.length : 0;
    const clientCount = Array.isArray(clientsSummary) ? clientsSummary.length : 0;

    return {
      totalAmount,
      paidAmount,
      outstandingAmount,
      overdueAmount,
      invoiceCount,
      clientCount
    };
  })();

  const cashflow = (() => {
    if (!Array.isArray(cashflowPoints) || cashflowPoints.length === 0) {
      return { points: [], min: 0, max: 0 };
    }
    const points = cashflowPoints
      .map((p) => {
        const amount = Number(p.amount || p.value || 0);
        const date = p.date || p.period || p.label || '';
        return { amount: isNaN(amount) ? 0 : amount, date };
      });
    const amounts = points.map((p) => p.amount);
    const min = Math.min.apply(null, amounts);
    const max = Math.max.apply(null, amounts);
    return { points, min, max };
  })();

  const renderSparkline = () => {
    const width = 320;
    const height = 64;
    const padding = 6;
    const pts = cashflow.points;
    if (!pts || pts.length === 0) {
      return (
        <div className="w-full h-16 flex items-center justify-center text-xs text-gray-500 bg-gray-50 rounded-md">
          No cashflow data
        </div>
      );
    }
    const min = cashflow.min;
    const max = cashflow.max;
    const range = max - min === 0 ? 1 : max - min;
    const step = pts.length > 1 ? (width - padding * 2) / (pts.length - 1) : 0;

    const toY = (val) => {
      const norm = (val - min) / range;
      return height - padding - norm * (height - padding * 2);
    };

    const d = pts.map((p, i) => {
      const x = padding + i * step;
      const y = toY(p.amount);
      return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
    }).join(' ');

    const last = pts[pts.length - 1] || { amount: 0 };
    const change = pts.length > 1 ? last.amount - pts[0].amount : 0;
    const changeClass = change > 0 ? 'text-green-600 bg-green-50' : change < 0 ? 'text-blue-600 bg-blue-50' : 'text-gray-600 bg-gray-50';

    return (
      <div className="w-full">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-20">
          <path d={d} fill="none" stroke="#2563eb" strokeWidth="2" />
          {pts.map((p, i) => {
            const x = padding + i * step;
            const y = height - padding - ((p.amount - min) / (range === 0 ? 1 : range)) * (height - padding * 2);
            return <circle key={i} cx={x} cy={y} r="2" fill="#2563eb" />;
          })}
        </svg>
        <div className="mt-2 flex items-center justify-between text-xs">
          <span className="text-gray-500">Range: {formatCurrency(min)} - {formatCurrency(max)}</span>
          <span className={`px-2 py-0.5 rounded ${changeClass}`}>Change: {formatCurrency(change)}</span>
        </div>
      </div>
    );
  };

  const renderKeyValue = (obj) => {
    const keys = obj && typeof obj === 'object' ? Object.keys(obj) : [];
    if (!keys || keys.length === 0) {
      return (
        <div className="text-sm text-gray-500">No details available</div>
      );
    }
    return (
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
        {keys.map((k) => (
          <div key={k} className="p-3 bg-gray-50 rounded-md">
            <div className="text-xs text-gray-500">{k}</div>
            <div className="text-sm font-medium text-gray-800 break-words">
              {typeof obj[k] === 'number' ? obj[k].toLocaleString() : (obj[k] === null || obj[k] === undefined ? '-' : String(obj[k]))}
            </div>
          </div>
        ))}
      </div>
    );
  };

  return (
    <div className="w-full max-w-3xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-6 relative">
      <div className="mb-4">
        <div className="flex items-start justify-between">
          <h3 className="text-lg font-semibold text-gray-900">{title}</h3>
          <div className="text-xs text-gray-500">{generatedAt ? `Generated ${formatDate(generatedAt)}` : ''}</div>
        </div>
        {metrics?.reportPeriod && (
          <div className="mt-1 text-sm text-gray-600">{metrics.reportPeriod}</div>
        )}
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm text-gray-600">Invoices</span>
            <span className="px-2 py-0.5 text-xs font-medium bg-blue-100 text-blue-700 rounded">
              {computed.invoiceCount}
            </span>
          </div>
          <div className="text-lg font-semibold text-gray-900">{computed.invoiceCount.toLocaleString()}</div>
          <div className="text-xs text-gray-500 mt-1">Total count</div>
        </div>
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm text-gray-600">Billed</span>
            <span className="px-2 py-0.5 text-xs font-medium bg-gray-100 text-gray-700 rounded">Sum</span>
          </div>
          <div className="text-lg font-semibold text-gray-900">{formatCurrency(computed.totalAmount)}</div>
          <div className="text-xs text-gray-500 mt-1">Total amount</div>
        </div>
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm text-gray-600">Paid</span>
            <span className="px-2 py-0.5 text-xs font-medium bg-green-100 text-green-700 rounded">Settled</span>
          </div>
          <div className="text-lg font-semibold text-gray-900">{formatCurrency(computed.paidAmount)}</div>
          <div className="text-xs text-gray-500 mt-1">Received</div>
        </div>
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-1">
            <span className="text-sm text-gray-600">Outstanding</span>
            <span className="px-2 py-0.5 text-xs font-medium bg-blue-100 text-blue-700 rounded">Open</span>
          </div>
          <div className="text-lg font-semibold text-gray-900">{formatCurrency(computed.outstandingAmount)}</div>
          <div className="text-xs text-gray-500 mt-1">Overdue: {formatCurrency(computed.overdueAmount)}</div>
        </div>
      </div>

      <div className="mb-6">
        <div className="flex items-center justify-between mb-3">
          <h4 className="text-lg font-semibold text-gray-900">Cashflow</h4>
          {metrics?.cashflowSummary && (
            <span className="text-xs text-gray-500">{metrics.cashflowSummary}</span>
          )}
        </div>
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          {renderSparkline()}
        </div>
      </div>

      <div className="mb-6">
        <h4 className="text-lg font-semibold text-gray-900 mb-3">Clients</h4>
        {Array.isArray(clientsSummary) && clientsSummary.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {clientsSummary.map((c, idx) => {
              const name = c.name || c.client || c.company || `Client ${idx + 1}`;
              const totalOutstanding = Number(c.totalOutstanding || c.outstanding || 0);
              const totalPaid = Number(c.totalPaid || c.paid || 0);
              const count = Number(c.invoiceCount || c.count || c.invoices || 0);
              return (
                <div key={idx} className="p-4 bg-gray-50 rounded-lg border border-gray-200 hover:shadow-md transition-shadow duration-200">
                  <div className="flex items-start justify-between">
                    <div className="text-sm font-medium text-gray-900 line-clamp-1">{name}</div>
                    <span className="ml-2 px-2 py-0.5 text-xs bg-blue-100 text-blue-700 rounded">{isNaN(count) ? '-' : count}</span>
                  </div>
                  <div className="mt-2 grid grid-cols-2 gap-3">
                    <div>
                      <div className="text-xs text-gray-500">Outstanding</div>
                      <div className="text-sm font-semibold text-gray-900">{formatCurrency(isNaN(totalOutstanding) ? 0 : totalOutstanding)}</div>
                    </div>
                    <div>
                      <div className="text-xs text-gray-500">Paid</div>
                      <div className="text-sm font-semibold text-gray-900">{formatCurrency(isNaN(totalPaid) ? 0 : totalPaid)}</div>
                    </div>
                  </div>
                  {c.notes && (
                    <div className="mt-2 text-xs text-gray-600 line-clamp-2">
                      {String(c.notes)}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ) : (
          <div className="p-4 bg-gray-50 rounded-md text-sm text-gray-600">No clients to display</div>
        )}
      </div>

      <div className="mb-6">
        <h4 className="text-lg font-semibold text-gray-900 mb-3">Invoices</h4>
        {Array.isArray(invoices) && invoices.length > 0 ? (
          <div className="overflow-x-auto border border-gray-200 rounded-lg">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Invoice</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Client</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Issued</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Due</th>
                  <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Amount</th>
                  <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-100">
                {invoices.slice(0, displayOptions.maxInvoices || 10).map((inv, idx) => {
                  const id = inv.id || inv.number || inv.reference || `#${idx + 1}`;
                  const client = inv.client || inv.customer || inv.account || '-';
                  const issued = inv.date || inv.issuedAt || inv.createdAt;
                  const due = inv.dueDate || inv.due || null;
                  const amt = Number(inv.amount || inv.total || inv.value || 0);
                  const statusRaw = (inv.status || '').toString();
                  const status = statusRaw || '—';
                  const statusLower = statusRaw.toLowerCase();
                  const statusClass = statusLower.includes('paid') ? 'bg-green-100 text-green-700' :
                    statusLower.includes('overdue') ? 'bg-blue-100 text-blue-700' :
                    'bg-gray-100 text-gray-700';
                  return (
                    <tr key={idx} className="hover:bg-gray-50">
                      <td className="px-4 py-3 text-sm text-gray-900">{id}</td>
                      <td className="px-4 py-3 text-sm text-gray-700">{client}</td>
                      <td className="px-4 py-3 text-sm text-gray-700">{formatDate(issued)}</td>
                      <td className="px-4 py-3 text-sm text-gray-700">{formatDate(due)}</td>
                      <td className="px-4 py-3 text-sm text-gray-900 text-right">{formatCurrency(isNaN(amt) ? 0 : amt)}</td>
                      <td className="px-4 py-3 text-sm">
                        <span className={`px-2 py-0.5 rounded ${statusClass}`}>{status}</span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            {invoices.length > (displayOptions.maxInvoices || 10) && (
              <div className="px-4 py-2 text-xs text-gray-500 bg-gray-50">
                Showing {displayOptions.maxInvoices || 10} of {invoices.length.toLocaleString()} invoices
              </div>
            )}
          </div>
        ) : (
          <div className="p-4 bg-gray-50 rounded-md text-sm text-gray-600">No invoices to display</div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-3">
            <h4 className="text-lg font-semibold text-gray-900">Metrics</h4>
            {metrics?.status && (
              <span className="px-2 py-0.5 text-xs bg-green-100 text-green-700 rounded">{String(metrics.status)}</span>
            )}
          </div>
          {renderKeyValue(metrics)}
        </div>
        <div className="p-4 bg-white rounded-lg border border-gray-200">
          <div className="flex items-center justify-between mb-3">
            <h4 className="text-lg font-semibold text-gray-900">Filters</h4>
            {filterSummary?.label && (
              <span className="px-2 py-0.5 text-xs bg-gray-100 text-gray-700 rounded">{String(filterSummary.label)}</span>
            )}
          </div>
          {renderKeyValue(filterSummary)}
        </div>
      </div>

      <div>
        <h4 className="text-lg font-semibold text-gray-900 mb-3">Notes</h4>
        {Array.isArray(notes) && notes.length > 0 ? (
          <div className="space-y-2">
            {notes.map((n, i) => (
              <div key={i} className="p-3 bg-gray-50 rounded-md text-sm text-gray-700">
                {String(n)}
              </div>
            ))}
          </div>
        ) : (
          <div className="p-3 bg-gray-50 rounded-md text-sm text-gray-600">No notes</div>
        )}
      </div>
    </div>
  );
};

const InvoiceFilters = (props) => {
  const {
    title,
    subtitle,
    appliedStatus,
    appliedClients = [],
    appliedDateRange = {},
    summary = {},
    legend = [],
    showLegend = false,
    generatedAt,
    notes,
  } = props;

  const getStatusBadge = (status) => {
    const normalized = (status || '').toLowerCase();
    if (normalized === 'paid') {
      return { text: 'Paid', className: 'bg-green-100 text-green-700' };
    }
    if (normalized === 'overdue') {
      return { text: 'Overdue', className: 'bg-blue-100 text-blue-700' };
    }
    if (normalized === 'unpaid') {
      return { text: 'Unpaid', className: 'bg-gray-100 text-gray-700' };
    }
    return { text: 'All', className: 'bg-gray-100 text-gray-700' };
  };

  const formatDate = (value) => {
    if (!value) {
      return '';
    }
    const d = new Date(value);
    return isNaN(d.getTime()) ? String(value) : d.toLocaleDateString();
  };

  const extractDateRange = (range) => {
    if (!range || typeof range !== 'object') {
      return { from: null, to: null };
    }
    const from = range.start || range.from || range.since || range.begin || null;
    const to = range.end || range.to || range.until || range.finish || null;
    return { from, to };
  };

  const { from, to } = extractDateRange(appliedDateRange);

  const clientLabel = (client, index) => {
    if (!client || typeof client !== 'object') {
      return `Client ${index + 1}`;
    }
    const name = client.name || client.title || client.company || null;
    const secondary = client.email || client.id || client.code || null;
    if (name && secondary) {
      return name + ' (' + secondary + ')';
    }
    if (name) {
      return name;
    }
    if (secondary) {
      return String(secondary);
    }
    const keys = Object.keys(client);
    if (keys.length > 0) {
      const firstKey = keys[0];
      return String(client[firstKey]);
    }
    return `Client ${index + 1}`;
  };

  const formatNumberLike = (val) => {
    const n = Number(val);
    if (!isNaN(n)) {
      return n % 1 === 0 ? n.toLocaleString() : n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }
    return String(val);
  };

  const status = getStatusBadge(appliedStatus);

  const hasClients = Array.isArray(appliedClients) && appliedClients.length > 0;
  const hasSummary = summary && typeof summary === 'object' && Object.keys(summary).length > 0;
  const hasLegend = showLegend && Array.isArray(legend) && legend.length > 0;

  return (
    <div className="w-full max-w-2xl mx-auto bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow duration-200">
      {(title || subtitle) && (
        <div className="mb-4">
          {title && <h3 className="text-lg font-semibold text-gray-900">{title}</h3>}
          {subtitle && <p className="text-sm text-gray-600 mt-1">{subtitle}</p>}
        </div>
      )}

      <div className="flex flex-wrap items-center gap-2 mb-4">
        <span className="text-sm text-gray-600">Status:</span>
        <span className={'px-2 py-1 text-xs font-medium rounded ' + status.className}>{status.text}</span>
        <span className="text-gray-300">•</span>
        <span className="text-sm text-gray-600">
          Date range: {from ? formatDate(from) : 'Any'} {to ? '— ' + formatDate(to) : ''}
        </span>
      </div>

      <div className="mb-4">
        <div className="text-sm font-medium text-gray-700 mb-2">Clients</div>
        {hasClients ? (
          <div className="flex flex-wrap gap-2">
            {appliedClients.map((c, idx) => (
              <span key={idx} className="px-2 py-1 bg-gray-50 text-gray-700 text-xs rounded border border-gray-200">
                {clientLabel(c, idx)}
              </span>
            ))}
          </div>
        ) : (
          <div className="p-3 bg-gray-50 rounded-md text-sm text-gray-500">No clients filtered</div>
        )}
      </div>

      <div className="mb-4">
        <div className="text-sm font-medium text-gray-700 mb-2">Summary</div>
        {hasSummary ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {Object.keys(summary).map((key) => {
              const value = summary[key];
              const display = typeof value === 'number' ? formatNumberLike(value) : String(value);
              return (
                <div key={key} className="p-3 bg-gray-50 rounded-md border border-gray-200">
                  <div className="text-xs text-gray-500 mb-1">{key}</div>
                  <div className="text-base font-semibold text-gray-900">{display}</div>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="p-3 bg-gray-50 rounded-md text-sm text-gray-500">No summary available</div>
        )}
      </div>

      {hasLegend && (
        <div className="mb-4">
          <div className="text-sm font-medium text-gray-700 mb-2">Legend</div>
          <div className="space-y-2">
            {legend.map((item, idx) => {
              const label = item && typeof item === 'object' ? item.label || item.name || 'Item ' + (idx + 1) : 'Item ' + (idx + 1);
              const color = item && typeof item === 'object' ? item.color || item.bgColor || '#e5e7eb' : '#e5e7eb';
              const value = item && typeof item === 'object' && 'value' in item ? item.value : null;
              const valueText = value !== null && value !== undefined ? (typeof value === 'number' ? formatNumberLike(value) : String(value)) : null;

              return (
                <div key={idx} className="flex items-center justify-between p-3 bg-white rounded-md border border-gray-200">
                  <div className="flex items-center gap-2">
                    <span className="inline-block w-3 h-3 rounded" style={{ backgroundColor: color }}></span>
                    <span className="text-sm text-gray-700">{label}</span>
                  </div>
                  {valueText ? <span className="text-sm font-medium text-gray-900">{valueText}</span> : <span className="text-sm text-gray-500">—</span>}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {(generatedAt || notes) && (
        <div className="pt-3 border-t border-gray-200">
          {generatedAt && (
            <div className="text-xs text-gray-500">Generated: {formatDate(generatedAt)}</div>
          )}
          {notes && (
            <div className="text-sm text-gray-600 mt-2 whitespace-pre-line">{notes}</div>
          )}
        </div>
      )}
    </div>
  );
};
